 15→	"github.com/entireio/cli/cmd/entire/cli/logging"
 16→	"golang.org/x/mod/semver"
 17→)
 18→
 19→// CheckAndNotify performs a version check and notifies the user if a newer version is available.
 20→// This is the main entry point for the version check system.
 21→// The function is silent on all errors to avoid interrupting CLI operations.
 22→func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
 23→	// Skip checks for dev builds
 24→	if currentVersion == "dev" || currentVersion == "" {
 25→		return
 26→	}
 27→
 28→	// Ensure the global config directory exists
 29→	if err := ensureGlobalConfigDir(); err != nil {
 30→		// Silent failure - don't block CLI operations
 31→		return
 32→	}
 33→
 34→	// Load the cache to check when we last fetched
 35→	cache, err := loadCache()
 36→	if err != nil {
 37→		cache = &VersionCache{}
 38→	}
 39→
 40→	// Skip if we checked recently (within 24 hours)
 41→	if time.Since(cache.LastCheckTime) < checkInterval {
 42→		return
 43→	}
 44→
 45→	// Fetch the latest version from GitHub API
 46→	latestVersion, err := fetchLatestVersion(ctx)
 47→
 48→	// Always update cache to avoid retrying on every CLI invocation
 49→	cache.LastCheckTime = time.Now()
 50→	if saveErr := saveCache(cache); saveErr != nil {
 51→		logging.Debug(ctx, "version check: failed to save cache",
 52→			"error", saveErr.Error())
 53→	}
 54→
 55→	if err != nil {
 56→		logging.Debug(ctx, "version check: failed to fetch latest version",
 57→			"error", err.Error())
 58→		return
 59→	}
 60→
 61→	// Show notification if outdated
 62→	if isOutdated(currentVersion, latestVersion) {
 63→		printNotification(w, currentVersion, latestVersion)
 64→	}
 65→}
 66→
 67→// globalConfigDirPath returns the expanded path to the global config directory (~/.config/entire).
 68→func globalConfigDirPath() (string, error) {
 69→	home, err := os.UserHomeDir()
 70→	if err != nil {
 71→		return "", fmt.Errorf("getting home directory: %w", err)
 72→	}
 73→	return filepath.Join(home, globalConfigDirName), nil
 74→}
 75→
 76→// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
 77→func ensureGlobalConfigDir() error {
 78→	configDir, err := globalConfigDirPath()
 79→	if err != nil {
 80→		return err
 81→	}
 82→
 83→	//nolint:gosec // ~/.config/entire is user home directory, 0o755 is appropriate
 84→	if err := os.MkdirAll(configDir, 0o755); err != nil {
 85→		return fmt.Errorf("creating config directory: %w", err)
 86→	}
 87→
 88→	return nil
 89→}
 90→
 91→// cacheFilePath returns the full path to the version check cache file.
 92→func cacheFilePath() (string, error) {
 93→	configDir, err := globalConfigDirPath()
 94→	if err != nil {
 95→		return "", err
 96→	}
 97→	return filepath.Join(configDir, cacheFileName), nil
 98→}
 99→
100→// loadCache loads the version check cache from disk.
101→// Returns an error if the file doesn't exist or is corrupted.
102→func loadCache() (*VersionCache, error) {
103→	filePath, err := cacheFilePath()
104→	if err != nil {
105→		return nil, err
106→	}
107→
108→	data, err := os.ReadFile(filePath) //nolint:gosec // cacheFilePath is safe
109→	if err != nil {
110→		return nil, fmt.Errorf("reading cache file: %w", err)
111→	}
112→
113→	var cache VersionCache
114→	if err := json.Unmarshal(data, &cache); err != nil {
115→		return nil, fmt.Errorf("parsing cache: %w", err)
116→	}
117→
118→	return &cache, nil
119→}
120→
121→// saveCache saves the version check cache to disk.
122→// Uses atomic write semantics (write to temp file, then rename).
123→func saveCache(cache *VersionCache) error {
124→	filePath, err := cacheFilePath()
125→	if err != nil {
126→		return err
127→	}
128→
129→	// Marshal to JSON
130→	data, err := json.MarshalIndent(cache, "", "  ")
131→	if err != nil {
132→		return fmt.Errorf("marshaling cache: %w", err)
133→	}
134→
135→	// Write to temp file first (atomic write)
136→	dir := filepath.Dir(filePath)
137→	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
138→	if err != nil {
139→		return fmt.Errorf("creating temp file: %w", err)
140→	}
141→	defer os.Remove(tmpFile.Name())
142→
143→	if _, err := tmpFile.Write(data); err != nil {
144→		_ = tmpFile.Close() // cleanup on error path
145→		return fmt.Errorf("writing cache: %w", err)
146→	}
147→
148→	if err := tmpFile.Close(); err != nil {
149→		return fmt.Errorf("closing temp file: %w", err)
150→	}
151→
152→	// Rename temp file to final location
153→
154→	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
155→		return fmt.Errorf("renaming cache file: %w", err)
156→	}
157→
158→	return nil
159→}
