161→// fetchLatestVersion fetches the latest version from the GitHub API.
162→// Returns a timeout-safe version check using the configured HTTP timeout.
163→func fetchLatestVersion(ctx context.Context) (string, error) {
164→	// Create a context with timeout for the HTTP request
165→	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
166→	defer cancel()
167→
168→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
169→	if err != nil {
170→		return "", fmt.Errorf("creating request: %w", err)
171→	}
172→
173→	// Set headers to identify as Entire CLI
174→	req.Header.Set("Accept", "application/vnd.github+json")
175→	req.Header.Set("User-Agent", "entire-cli")
176→
177→	client := &http.Client{}
178→	resp, err := client.Do(req)
179→	if err != nil {
180→		return "", fmt.Errorf("fetching release info: %w", err)
181→	}
182→	defer resp.Body.Close()
183→
184→	if resp.StatusCode != http.StatusOK {
185→		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
186→	}
187→
188→	// Read response body (limit to 1MB to prevent memory exhaustion)
189→	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
190→	if err != nil {
191→		return "", fmt.Errorf("reading response: %w", err)
192→	}
193→
194→	// Parse GitHub release response
195→	version, err := parseGitHubRelease(body)
196→	if err != nil {
197→		return "", fmt.Errorf("parsing release: %w", err)
198→	}
199→
200→	return version, nil
201→}
202→
203→// parseGitHubRelease parses the GitHub API response and extracts the latest stable version.
204→// Filters out prerelease versions.
205→func parseGitHubRelease(body []byte) (string, error) {
206→	var release GitHubRelease
207→	if err := json.Unmarshal(body, &release); err != nil {
208→		return "", fmt.Errorf("parsing JSON: %w", err)
209→	}
210→
211→	// Skip prerelease versions
212→	if release.Prerelease {
213→		return "", errors.New("only prerelease versions available")
214→	}
215→
216→	// Ensure we have a tag name
217→	if release.TagName == "" {
218→		return "", errors.New("empty tag name")
219→	}
220→
221→	return release.TagName, nil
222→}
223→
224→// isOutdated compares current and latest versions using semantic versioning.
225→// Returns true if current < latest.
226→func isOutdated(current, latest string) bool {
227→	// Ensure versions have "v" prefix for semver package
228→	if !strings.HasPrefix(current, "v") {
229→		current = "v" + current
230→	}
231→	if !strings.HasPrefix(latest, "v") {
232→		latest = "v" + latest
233→	}
234→
235→	// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
236→	// These are local development builds and shouldn't trigger update notifications.
237→	// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
238→	if strings.Contains(semver.Prerelease(current), "dev") {
239→		return false
240→	}
241→
242→	// semver.Compare returns -1 if current < latest
243→	return semver.Compare(current, latest) < 0
244→}
245→
246→// executablePath is the function used to get the current executable path.
247→// It's a variable so tests can override it.
248→var executablePath = os.Executable
249→
250→// updateCommand returns the appropriate update instruction based on how the binary was installed.
251→func updateCommand() string {
252→	execPath, err := executablePath()
253→	if err != nil {
254→		return "curl -fsSL https://entire.io/install.sh | bash"
255→	}
256→
257→	// Resolve symlinks to find the real path (Homebrew symlinks from bin/ to Cellar/)
258→	realPath, err := filepath.EvalSymlinks(execPath)
259→	if err != nil {
260→		realPath = execPath
261→	}
262→
263→	if strings.Contains(realPath, "/Cellar/") || strings.Contains(realPath, "/opt/homebrew/") || strings.Contains(realPath, "/linuxbrew/") {
264→		return "brew upgrade entire"
265→	}
266→
267→	if strings.Contains(realPath, "/mise/installs/") {
268→		return "mise upgrade entire"
269→	}
270→
271→	return "curl -fsSL https://entire.io/install.sh | bash"
272→}
273→
274→// printNotification prints the version update notification to the user.
275→func printNotification(w io.Writer, current, latest string) {
276→	msg := fmt.Sprintf("\nA newer version of Entire CLI is available: %s (current: %s)\nRun '%s' to update.\n",
277→		latest, current, updateCommand())
278→	fmt.Fprint(w, msg)
279→}
