 36→func newLoginCmd() *cobra.Command {
 37→	var insecureHTTPAuth bool
 38→
 39→	cmd := &cobra.Command{
 40→		Use:   "login",
 41→		Short: "Log in to Entire",
 42→		RunE: func(cmd *cobra.Command, _ []string) error {
 43→			client := auth.NewClient(nil)
 44→
 45→			if !insecureHTTPAuth {
 46→				if err := apiurl.RequireSecureURL(client.BaseURL()); err != nil {
 47→					return fmt.Errorf("base URL check: %w", err)
 48→				}
 49→			}
 50→
 51→			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), client, openBrowser)
 52→		},
 53→	}
 54→
 55→	cmd.Flags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
 56→	if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
 57→		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
 58→	}
 59→
 60→	return cmd
 61→}
