108→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
109→	expiry := time.Duration(expiresIn) * time.Second
110→	if expiry <= 0 || expiry > maxExpiresIn {
111→		expiry = maxExpiresIn
112→	}
113→	deadline := time.Now().Add(expiry)
114→	pollInterval := time.Duration(interval) * time.Second
115→	if pollInterval <= 0 {
116→		pollInterval = fallbackDeviceAuthPollInterval
117→	}
118→
119→	consecutiveErrors := 0
120→
121→	for {
122→		if time.Now().After(deadline) {
123→			return "", errors.New("device authorization expired")
124→		}
125→
126→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
127→		if err != nil {
128→			consecutiveErrors++
129→			if consecutiveErrors >= maxTransientErrors {
130→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
131→			}
132→			// Transient error — wait and retry.
133→			select {
134→			case <-ctx.Done():
135→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
136→			case <-time.After(pollInterval):
137→			}
138→			continue
139→		}
140→		consecutiveErrors = 0
141→
142→		switch result.Error {
143→		case "":
144→			if result.AccessToken == "" {
145→				return "", errors.New("device authorization completed without a token")
146→			}
147→			return result.AccessToken, nil
148→		case "authorization_pending":
149→			// no-op, will sleep and retry below
150→		case "slow_down":
151→			pollInterval += slowDownBackoff
152→			if pollInterval > maxPollInterval {
153→				pollInterval = maxPollInterval
154→			}
155→		case "access_denied":
156→			return "", errors.New("device authorization denied")
157→		case "expired_token":
158→			return "", errors.New("device authorization expired")
159→		default:
160→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
161→		}
162→
163→		select {
164→		case <-ctx.Done():
165→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
166→		case <-time.After(pollInterval):
167→		}
168→	}
169→}
170→
171→// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
172→// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
173→// Returns ctx.Err() if the context is cancelled before the user presses Enter.
174→func waitForEnter(ctx context.Context) error {
175→	tty, err := os.Open("/dev/tty")
176→	if err != nil {
177→		return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
178→	}
179→
180→	done := make(chan error, 1)
181→	go func() {
182→		reader := bufio.NewReader(tty)
183→		_, err := reader.ReadString('\n')
184→		done <- err
185→	}()
186→
187→	select {
188→	case <-ctx.Done():
189→		// Close tty to unblock the reading goroutine.
190→		_ = tty.Close()
191→		return fmt.Errorf("interrupted: %w", ctx.Err())
192→	case <-done:
193→		_ = tty.Close()
194→		return nil
195→	}
196→}
197→
198→func openBrowser(ctx context.Context, browserURL string) error {
199→	u, err := url.Parse(browserURL)
200→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
201→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
202→	}
203→
204→	var command string
205→	var args []string
206→
207→	switch runtime.GOOS {
208→	case "darwin":
209→		command = "open"
210→		args = []string{browserURL}
211→	case "linux":
212→		command = "xdg-open"
213→		args = []string{browserURL}
214→	case "windows":
215→		command = "cmd"
216→		args = []string{"/c", "start", "", browserURL}
217→	default:
218→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
219→	}
220→
221→	cmd := exec.CommandContext(ctx, command, args...)
222→	if err := cmd.Start(); err != nil {
223→		return fmt.Errorf("start browser command %q: %w", command, err)
224→	}
225→
226→	if err := cmd.Process.Release(); err != nil {
227→		return fmt.Errorf("release browser process: %w", err)
228→	}
229→
230→	return nil
231→}
