 38→// EnsureBranch creates the entire/trails/v1 orphan branch if it doesn't exist.
 39→func (s *Store) EnsureBranch() error {
 40→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
 41→	_, err := s.repo.Reference(refName, true)
 42→	if err == nil {
 43→		return nil // Branch already exists
 44→	}
 45→
 46→	// Create orphan branch with empty tree
 47→	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 48→	if err != nil {
 49→		return fmt.Errorf("failed to build empty tree: %w", err)
 50→	}
 51→
 52→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
 53→	commitHash, err := checkpoint.CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
 54→	if err != nil {
 55→		return fmt.Errorf("failed to create initial commit: %w", err)
 56→	}
 57→
 58→	newRef := plumbing.NewHashReference(refName, commitHash)
 59→	if err := s.repo.Storer.SetReference(newRef); err != nil {
 60→		return fmt.Errorf("failed to set branch reference: %w", err)
 61→	}
 62→	return nil
 63→}
 64→
 65→// Write writes trail metadata, discussion, and checkpoints to the entire/trails/v1 branch.
 66→// If checkpoints is nil, an empty checkpoints list is written.
 67→func (s *Store) Write(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints) error {
 68→	if metadata.TrailID.IsEmpty() {
 69→		return errors.New("trail ID is required")
 70→	}
 71→
 72→	if err := s.EnsureBranch(); err != nil {
 73→		return fmt.Errorf("failed to ensure trails branch: %w", err)
 74→	}
 75→
 76→	commitHash, rootTreeHash, err := s.getBranchRef()
 77→	if err != nil {
 78→		return fmt.Errorf("failed to get branch ref: %w", err)
 79→	}
 80→
 81→	// Build blob entries for the trail's 3 files
 82→	trailEntries, err := s.buildTrailEntries(metadata, discussion, checkpoints)
 83→	if err != nil {
 84→		return err
 85→	}
 86→
 87→	// Splice into tree at [shard, suffix] — preserves sibling trails automatically
 88→	shard, suffix := metadata.TrailID.ShardParts()
 89→	newTreeHash, err := checkpoint.UpdateSubtree(
 90→		s.repo, rootTreeHash,
 91→		[]string{shard, suffix},
 92→		trailEntries,
 93→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.ReplaceAll},
 94→	)
 95→	if err != nil {
 96→		return fmt.Errorf("failed to update subtree: %w", err)
 97→	}
 98→
 99→	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
100→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
101→}
