142→// Read reads a trail by its ID from the entire/trails/v1 branch.
143→func (s *Store) Read(trailID ID) (*Metadata, *Discussion, *Checkpoints, error) {
144→	if err := ValidateID(string(trailID)); err != nil {
145→		return nil, nil, nil, err
146→	}
147→
148→	tree, err := s.getBranchTree()
149→	if err != nil {
150→		return nil, nil, nil, err
151→	}
152→
153→	basePath := trailID.Path() + "/"
154→
155→	// Read metadata
156→	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
157→	if err != nil {
158→		return nil, nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
159→	}
160→	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
161→	if err != nil {
162→		return nil, nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
163→	}
164→	metadataReader, err := metadataBlob.Reader()
165→	if err != nil {
166→		return nil, nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
167→	}
168→	defer metadataReader.Close()
169→
170→	var metadata Metadata
171→	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
172→		return nil, nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
173→	}
174→
175→	// Read discussion (optional, may not exist yet)
176→	var discussion Discussion
177→	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
178→	if err == nil {
179→		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
180→		if blobErr == nil {
181→			discussionReader, readerErr := discussionBlob.Reader()
182→			if readerErr == nil {
183→				//nolint:errcheck,gosec // best-effort decode of optional discussion
184→				json.NewDecoder(discussionReader).Decode(&discussion)
185→				_ = discussionReader.Close()
186→			}
187→		}
188→	}
189→
190→	// Read checkpoints (optional, may not exist yet)
191→	var checkpoints Checkpoints
192→	checkpointsEntry, err := tree.FindEntry(basePath + checkpointsFile)
193→	if err == nil {
194→		checkpointsBlob, blobErr := s.repo.BlobObject(checkpointsEntry.Hash)
195→		if blobErr == nil {
196→			checkpointsReader, readerErr := checkpointsBlob.Reader()
197→			if readerErr == nil {
198→				//nolint:errcheck,gosec // best-effort decode of optional checkpoints
199→				json.NewDecoder(checkpointsReader).Decode(&checkpoints)
200→				_ = checkpointsReader.Close()
201→			}
202→		}
203→	}
204→
205→	return &metadata, &discussion, &checkpoints, nil
206→}
