224→// List returns all trail metadata from the entire/trails/v1 branch.
225→func (s *Store) List() ([]*Metadata, error) {
226→	tree, err := s.getBranchTree()
227→	if err != nil {
228→		// Branch doesn't exist yet — no trails
229→		return nil, nil //nolint:nilerr // Expected when no trails exist yet
230→	}
231→
232→	var trails []*Metadata
233→	entries := make(map[string]object.TreeEntry)
234→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
235→		return nil, fmt.Errorf("failed to flatten tree: %w", err)
236→	}
237→
238→	// Find all metadata.json files
239→	for path, entry := range entries {
240→		if !strings.HasSuffix(path, "/"+metadataFile) {
241→			continue
242→		}
243→
244→		blob, err := s.repo.BlobObject(entry.Hash)
245→		if err != nil {
246→			continue
247→		}
248→		reader, err := blob.Reader()
249→		if err != nil {
250→			continue
251→		}
252→
253→		var metadata Metadata
254→		decodeErr := json.NewDecoder(reader).Decode(&metadata)
255→		_ = reader.Close()
256→		if decodeErr != nil {
257→			continue
258→		}
259→
260→		trails = append(trails, &metadata)
261→	}
262→
263→	return trails, nil
264→}
