266→// Update updates an existing trail's metadata. It reads the current metadata,
267→// applies the provided update function, and writes it back.
268→func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
269→	// ValidateID is called by Read, no need to duplicate here
270→	metadata, discussion, checkpoints, err := s.Read(trailID)
271→	if err != nil {
272→		return fmt.Errorf("failed to read trail for update: %w", err)
273→	}
274→
275→	updateFn(metadata)
276→	metadata.UpdatedAt = time.Now()
277→
278→	return s.Write(metadata, discussion, checkpoints)
279→}
