281→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
282→// Only reads and writes the checkpoints.json file — metadata and discussion are untouched.
283→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
284→	if err := ValidateID(string(trailID)); err != nil {
285→		return err
286→	}
287→
288→	if err := s.EnsureBranch(); err != nil {
289→		return fmt.Errorf("failed to ensure trails branch: %w", err)
290→	}
291→
292→	commitHash, rootTreeHash, err := s.getBranchRef()
293→	if err != nil {
294→		return fmt.Errorf("failed to get branch ref: %w", err)
295→	}
296→
297→	// Navigate to the trail's subtree and read only checkpoints.json
298→	shard, suffix := trailID.ShardParts()
299→	trailTree, err := s.navigateToTrailTree(rootTreeHash, shard, suffix)
300→	if err != nil {
301→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
302→	}
303→
304→	checkpoints, err := s.readCheckpointsFromTrailTree(trailTree)
305→	if err != nil {
306→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
307→	}
308→
309→	// Prepend new ref (newest first)
310→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
311→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
312→	checkpoints.Checkpoints[0] = ref
313→
314→	// Create new blob and splice back — MergeKeepExisting preserves metadata.json and discussion.json
315→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
316→	if err != nil {
317→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
318→	}
319→	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
320→	if err != nil {
321→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
322→	}
323→
324→	newTreeHash, err := checkpoint.UpdateSubtree(
325→		s.repo, rootTreeHash,
326→		[]string{shard, suffix},
327→		[]object.TreeEntry{{Name: checkpointsFile, Mode: filemode.Regular, Hash: blobHash}},
328→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
329→	)
330→	if err != nil {
331→		return fmt.Errorf("failed to update subtree: %w", err)
332→	}
333→
334→	commitMsg := fmt.Sprintf("Add checkpoint to trail: %s", trailID)
335→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
336→}
