338→// Delete removes a trail from the entire/trails/v1 branch.
339→func (s *Store) Delete(trailID ID) error {
340→	if err := ValidateID(string(trailID)); err != nil {
341→		return err
342→	}
343→
344→	if err := s.EnsureBranch(); err != nil {
345→		return fmt.Errorf("failed to ensure trails branch: %w", err)
346→	}
347→
348→	commitHash, rootTreeHash, err := s.getBranchRef()
349→	if err != nil {
350→		return fmt.Errorf("failed to get branch ref: %w", err)
351→	}
352→
353→	// Verify the trail exists by navigating the tree at O(depth)
354→	shard, suffix := trailID.ShardParts()
355→	if _, err := s.navigateToTrailTree(rootTreeHash, shard, suffix); err != nil {
356→		return err
357→	}
358→
359→	// Delete the trail's subtree by removing it from the shard directory
360→	newTreeHash, err := checkpoint.UpdateSubtree(
361→		s.repo, rootTreeHash,
362→		[]string{shard},
363→		nil,
364→		checkpoint.UpdateSubtreeOptions{
365→			MergeMode:   checkpoint.MergeKeepExisting,
366→			DeleteNames: []string{suffix},
367→		},
368→	)
369→	if err != nil {
370→		return fmt.Errorf("failed to update subtree: %w", err)
371→	}
372→
373→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
374→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
375→}
