377→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
378→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
379→	rootTree, err := s.repo.TreeObject(rootTreeHash)
380→	if err != nil {
381→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
382→	}
383→
384→	shardEntry, err := rootTree.FindEntry(shard)
385→	if err != nil {
386→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
387→	}
388→
389→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
390→	if err != nil {
391→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
392→	}
393→
394→	trailEntry, err := shardTree.FindEntry(suffix)
395→	if err != nil {
396→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
397→	}
398→
399→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
400→	if err != nil {
401→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
402→	}
403→
404→	return trailTree, nil
405→}
