407→// readCheckpointsFromTrailTree reads checkpoints.json from a trail's subtree.
408→// Returns empty checkpoints if the file doesn't exist yet.
409→func (s *Store) readCheckpointsFromTrailTree(trailTree *object.Tree) (*Checkpoints, error) {
410→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
411→	if err != nil {
412→		// No checkpoints file yet — return empty
413→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
414→	}
415→
416→	blob, err := s.repo.BlobObject(cpEntry.Hash)
417→	if err != nil {
418→		return nil, fmt.Errorf("failed to read checkpoints blob: %w", err)
419→	}
420→
421→	reader, err := blob.Reader()
422→	if err != nil {
423→		return nil, fmt.Errorf("failed to open checkpoints reader: %w", err)
424→	}
425→	defer reader.Close()
426→
427→	var checkpoints Checkpoints
428→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
429→		return nil, fmt.Errorf("failed to decode checkpoints: %w", err)
430→	}
431→
432→	return &checkpoints, nil
433→}
