435→// commitAndUpdateRef creates a commit and updates the trails branch reference.
436→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
437→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
438→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
439→	if err != nil {
440→		return fmt.Errorf("failed to create commit: %w", err)
441→	}
442→
443→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
444→	if err := s.repo.Storer.SetReference(newRef); err != nil {
445→		return fmt.Errorf("failed to update branch reference: %w", err)
446→	}
447→	return nil
448→}
