450→// getBranchRef returns the commit hash and root tree hash for the entire/trails/v1 branch HEAD
451→// without flattening the tree. Falls back to remote tracking branch if local is missing.
452→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
453→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
454→	ref, refErr := s.repo.Reference(refName, true)
455→	if refErr != nil {
456→		// Try remote tracking branch
457→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
458→		ref, refErr = s.repo.Reference(remoteRefName, true)
459→		if refErr != nil {
460→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
461→		}
462→	}
463→
464→	commit, err := s.repo.CommitObject(ref.Hash())
465→	if err != nil {
466→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
467→	}
468→
469→	return ref.Hash(), commit.TreeHash, nil
470→}
471→
472→// getBranchTree returns the tree for the entire/trails/v1 branch HEAD.
473→func (s *Store) getBranchTree() (*object.Tree, error) {
474→	_, rootTreeHash, err := s.getBranchRef()
475→	if err != nil {
476→		return nil, err
477→	}
478→
479→	tree, err := s.repo.TreeObject(rootTreeHash)
480→	if err != nil {
481→		return nil, fmt.Errorf("failed to get tree: %w", err)
482→	}
483→
484→	return tree, nil
485→}
