 48→	r.Header.Set("User-Agent", userAgent)
 49→	if r.Header.Get("Accept") == "" {
 50→		r.Header.Set("Accept", "application/json")
 51→	}
 52→	return t.base.RoundTrip(r)
 53→}
 54→
 55→// Get sends an authenticated GET request to the given API-relative path.
 56→func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
 57→	return c.do(ctx, http.MethodGet, path, nil)
 58→}
 59→
 60→// Post sends an authenticated POST request with a JSON body to the given API-relative path.
 61→func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
 62→	var reader io.Reader
 63→	if body != nil {
 64→		data, err := json.Marshal(body)
 65→		if err != nil {
 66→			return nil, fmt.Errorf("marshal request body: %w", err)
 67→		}
 68→		reader = bytes.NewReader(data)
 69→	}
 70→	return c.do(ctx, http.MethodPost, path, reader)
 71→}
 72→
 73→// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
 74→func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
 75→	var reader io.Reader
 76→	if body != nil {
 77→		data, err := json.Marshal(body)
 78→		if err != nil {
 79→			return nil, fmt.Errorf("marshal request body: %w", err)
 80→		}
 81→		reader = bytes.NewReader(data)
 82→	}
 83→	return c.do(ctx, http.MethodPut, path, reader)
 84→}
 85→
 86→// Delete sends an authenticated DELETE request to the given API-relative path.
 87→func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
 88→	return c.do(ctx, http.MethodDelete, path, nil)
 89→}
 90→
 91→func (c *Client) do(ctx context.Context, method, path string, body io.Reader) (*http.Response, error) {
 92→	endpoint, err := ResolveURLFromBase(c.baseURL, path)
 93→	if err != nil {
 94→		return nil, fmt.Errorf("resolve URL %s: %w", path, err)
 95→	}
 96→
 97→	req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
 98→	if err != nil {
 99→		return nil, fmt.Errorf("create request: %w", err)
100→	}
101→
102→	if body != nil {
103→		req.Header.Set("Content-Type", "application/json")
104→	}
105→
106→	return c.httpClient.Do(req)
107→}
108→
109→// DecodeJSON reads the response body and decodes it into dest.
110→// It limits the body size to protect against unbounded reads.
111→func DecodeJSON(resp *http.Response, dest any) error {
112→	defer resp.Body.Close()
113→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
114→	if err != nil {
115→		return fmt.Errorf("read response body: %w", err)
116→	}
117→
118→	if err := json.Unmarshal(body, dest); err != nil {
119→		return fmt.Errorf("decode JSON response: %w", err)
120→	}
121→
122→	return nil
123→}
124→
125→// ErrorResponse represents a standard API error response.
126→type ErrorResponse struct {
127→	Error string `json:"error"`
128→}
129→
130→// CheckResponse returns an error if the response status code indicates failure.
131→// For non-2xx responses, it attempts to parse the error message from the body.
132→func CheckResponse(resp *http.Response) error {
133→	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
134→		return nil
135→	}
136→
137→	defer resp.Body.Close()
138→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
139→	if err != nil {
140→		return fmt.Errorf("API error: status %d", resp.StatusCode)
141→	}
142→
143→	var apiErr ErrorResponse
144→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
145→		return fmt.Errorf("API error: %s (status %d)", apiErr.Error, resp.StatusCode)
146→	}
147→
148→	text := strings.TrimSpace(string(body))
149→	if text != "" {
150→		return fmt.Errorf("API error: %s (status %d)", text, resp.StatusCode)
151→	}
152→
153→	return fmt.Errorf("API error: status %d", resp.StatusCode)
154→}
