 77→// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
 78→func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
 79→	var reader io.Reader
 80→	if body != nil {
 81→		data, err := json.Marshal(body)
 82→		if err != nil {
 83→			return nil, fmt.Errorf("marshal request body: %w", err)
 84→		}
 85→		reader = bytes.NewReader(data)
 86→	}
 87→	return c.do(ctx, http.MethodPut, path, reader)
 88→}
 89→
 90→// Delete sends an authenticated DELETE request to the given API-relative path.
 91→func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
 92→	return c.do(ctx, http.MethodDelete, path, nil)
 93→}
 94→
 95→func (c *Client) do(ctx context.Context, method, path string, body io.Reader) (*http.Response, error) {
 96→	endpoint, err := ResolveURLFromBase(c.baseURL, path)
 97→	if err != nil {
 98→		return nil, fmt.Errorf("resolve URL %s: %w", path, err)
 99→	}
100→
101→	req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
102→	if err != nil {
103→		return nil, fmt.Errorf("create request: %w", err)
104→	}
105→
106→	if body != nil {
107→		req.Header.Set("Content-Type", "application/json")
108→	}
109→
110→	resp, err := c.httpClient.Do(req)
111→	if err != nil {
112→		return nil, fmt.Errorf("%s %s: %w", method, path, err)
113→	}
114→	return resp, nil
115→}
