117→// DecodeJSON reads the response body and decodes it into dest.
118→// It limits the body size to protect against unbounded reads.
119→func DecodeJSON(resp *http.Response, dest any) error {
120→	defer resp.Body.Close()
121→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
122→	if err != nil {
123→		return fmt.Errorf("read response body: %w", err)
124→	}
125→
126→	if err := json.Unmarshal(body, dest); err != nil {
127→		return fmt.Errorf("decode JSON response: %w", err)
128→	}
129→
130→	return nil
131→}
132→
133→// ErrorResponse represents a standard API error response.
134→type ErrorResponse struct {
135→	Error string `json:"error"`
136→}
137→
138→// CheckResponse returns an error if the response status code indicates failure.
139→// For non-2xx responses, it attempts to parse the error message from the body.
140→func CheckResponse(resp *http.Response) error {
141→	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
142→		return nil
143→	}
144→
145→	defer resp.Body.Close()
146→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
147→	if err != nil {
148→		return fmt.Errorf("API error: status %d", resp.StatusCode)
149→	}
150→
151→	var apiErr ErrorResponse
152→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
153→		return fmt.Errorf("API error: %s (status %d)", apiErr.Error, resp.StatusCode)
154→	}
155→
156→	text := strings.TrimSpace(string(body))
157→	if text != "" {
158→		return fmt.Errorf("API error: %s (status %d)", text, resp.StatusCode)
159→	}
160→
161→	return fmt.Errorf("API error: status %d", resp.StatusCode)
162→}
