489→func formatValidStatuses() string {
490→	statuses := trail.ValidStatuses()
491→	names := make([]string, len(statuses))
492→	for i, s := range statuses {
493→		names[i] = string(s)
494→	}
495→	return strings.Join(names, ", ")
496→}
