498→// runTrailCreateInteractive runs the interactive form for trail creation.
499→// Prompts for title, body, branch (derived from title), and status.
500→func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
501→	// Step 1: Title and body
502→	form := NewAccessibleForm(
503→		huh.NewGroup(
504→			huh.NewInput().
505→				Title("Trail title").
506→				Placeholder("What are you working on?").
507→				Value(title),
508→			huh.NewText().
509→				Title("Body (optional)").
510→				Value(body),
511→		),
512→	)
513→	if err := form.Run(); err != nil {
514→		return fmt.Errorf("form cancelled: %w", err)
515→	}
516→	*title = strings.TrimSpace(*title)
517→	if *title == "" {
518→		return errors.New("trail title is required")
519→	}
520→
521→	// Step 2: Branch (derived from title) and status
522→	suggested := slugifyTitle(*title)
523→	*branch = suggested
524→
525→	// Build status options, excluding done/closed
526→	var statusOptions []huh.Option[string]
527→	for _, s := range trail.ValidStatuses() {
528→		if s == trail.StatusMerged || s == trail.StatusClosed {
529→			continue
530→		}
531→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
532→	}
533→	if *statusStr == "" {
534→		*statusStr = string(trail.StatusDraft)
535→	}
536→
537→	form = NewAccessibleForm(
538→		huh.NewGroup(
539→			huh.NewInput().
540→				Title("Branch name").
541→				Placeholder(suggested).
542→				Value(branch),
543→			huh.NewSelect[string]().
544→				Title("Status").
545→				Options(statusOptions...).
546→				Value(statusStr),
547→		),
548→	)
549→	if err := form.Run(); err != nil {
550→		return fmt.Errorf("form cancelled: %w", err)
551→	}
552→	*branch = strings.TrimSpace(*branch)
553→	if *branch == "" {
554→		*branch = suggested
555→	}
556→	return nil
557→}
558→
559→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
560→// Best-effort: silently ignores errors (e.g., no remote, no network).
561→func fetchTrailsBranch() {
562→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
563→	defer cancel()
564→	branchName := paths.TrailsBranchName
565→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
566→
567→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
568→	// Ensure non-interactive fetch in hook/agent contexts
569→	cmd.Stdin = nil
570→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
571→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
572→}
573→
574→// getTrailAuthor returns the GitHub username for the trail author.
575→// Falls back to git user.name if gh CLI is unavailable or not authenticated.
576→func getTrailAuthor(repo *git.Repository) string {
577→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
578→	defer cancel()
579→	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
580→	if output, err := cmd.Output(); err == nil {
581→		if login := strings.TrimSpace(string(output)); login != "" {
582→			return login
583→		}
584→	}
585→	name, _ := strategy.GetGitAuthorFromRepo(repo)
586→	return name
587→}
588→
589→// slugifyTitle converts a title string into a branch-friendly slug.
590→// Example: "Add user authentication" -> "add-user-authentication"
591→func slugifyTitle(title string) string {
592→	s := strings.ToLower(strings.TrimSpace(title))
593→	// Replace spaces and underscores with hyphens
594→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
595→	// Remove anything that's not alphanumeric, hyphen, or slash
596→	var b strings.Builder
597→	prevHyphen := false
598→	for _, r := range s {
599→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
600→			b.WriteRune(r)
601→			prevHyphen = false
602→		} else if r == '-' && !prevHyphen {
603→			b.WriteRune('-')
604→			prevHyphen = true
605→		}
606→	}
607→	return strings.Trim(b.String(), "-")
608→}
609→
610→// branchNeedsCreation checks if a branch exists locally.
611→func branchNeedsCreation(repo *git.Repository, branchName string) bool {
612→	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
613→	return err != nil
614→}
615→
616→// createBranch creates a new local branch pointing at HEAD without checking it out.
617→func createBranch(repo *git.Repository, branchName string) error {
618→	head, err := repo.Head()
619→	if err != nil {
620→		return fmt.Errorf("failed to get HEAD: %w", err)
621→	}
622→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
623→	if err := repo.Storer.SetReference(ref); err != nil {
624→		return fmt.Errorf("failed to create branch ref: %w", err)
625→	}
626→	return nil
627→}
628→
629→// pushBranchToOrigin pushes a branch to the origin remote.
630→func pushBranchToOrigin(branchName string) error {
631→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
632→	defer cancel()
633→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
634→	if output, err := cmd.CombinedOutput(); err != nil {
635→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
636→	}
637→	return nil
638→}
