package apiurl

import (
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// TestDebugToken is a manual debugging helper — run with:
//
//	go test ./cmd/entire/cli/api/ -run TestDebugToken -v
func TestDebugToken(t *testing.T) {
	baseURL := BaseURL()
	fmt.Printf("Base URL: %s\n", baseURL)
	fmt.Printf("ENTIRE_API_BASE_URL env: %q\n", os.Getenv(BaseURLEnvVar))

	store := auth.NewStore()
	token, err := store.GetToken(baseURL)
	if err != nil {
		fmt.Printf("Token lookup error: %v\n", err)
		return
	}
	if token == "" {
		fmt.Println("No token found in keyring for this base URL")
		return
	}

	fmt.Printf("Token length: %d\n", len(token))
	if len(token) > 8 {
		fmt.Printf("Token prefix: %s...\n", token[:8])
	}
	fmt.Printf("Starts with ent_: %v\n", strings.HasPrefix(token, "ent_"))
}

